<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/bootstrap.php';require_once __DIR__ . '/../includes/auth.php';
$user=current_user();if(!$user||!in_array($user['role'],['Administrator','Head'],true)){http_response_code(403);exit('Access denied.');}if($_SERVER['REQUEST_METHOD']!=='POST'||!verify_csrf()){http_response_code(419);exit('This form has expired. Refresh the page and try again.');}$id=filter_var($_POST['candidate_id']??null,FILTER_VALIDATE_INT);if(!$id){$_SESSION['error']='A valid candidate entry is required.';header('Location: ../?page=exams');exit;}$pdo=db();try{$pdo->beginTransaction();$q=$pdo->prepare('SELECT ec.id,ec.status,es.id AS session_id,es.status AS session_status,es.opens_on,es.entry_deadline,es.level FROM exam_candidates ec JOIN exam_sessions es ON es.id=ec.session_id WHERE ec.id=:id FOR UPDATE');$q->execute(['id'=>$id]);$entry=$q->fetch();$today=date('Y-m-d');if(!$entry||$entry['status']!=='Draft'||$entry['session_status']!=='Open'||$today<$entry['opens_on']||$today>$entry['entry_deadline'])throw new DomainException('This draft cannot be submitted because its entry window is closed.');$q=$pdo->prepare('SELECT COUNT(*) FROM exam_candidate_subjects WHERE candidate_id=:id');$q->execute(['id'=>$id]);$count=(int)$q->fetchColumn();if($count<1||($entry['level']==='O-Level'&&$count>9))throw new DomainException($entry['level']==='O-Level'?'An O-Level entry needs 1–9 subjects.':'An entry needs at least one subject.');$q=$pdo->prepare("UPDATE exam_candidates SET status='Submitted',submitted_by=:user,submitted_at=NOW() WHERE id=:id AND status='Draft'");$q->execute(['user'=>$user['id'],'id'=>$id]);audit_log('exams.candidate_submitted','exam_candidates',$id,['subject_count'=>$count]);$pdo->commit();$_SESSION['notice']='Candidate entry submitted for the school examination register.';header('Location: ../?page=exams&session='.(int)$entry['session_id']);exit;}catch(DomainException $e){if($pdo->inTransaction())$pdo->rollBack();$_SESSION['error']=$e->getMessage();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();error_log('Exam candidate submission failed: '.$e->getMessage());$_SESSION['error']='Could not submit this candidate entry.';}header('Location: ../?page=exams&candidate='.(int)$id);exit;
